import type { StoredWorkflowGraph } from '../graph';
import type { ExecutionMode, ExecutionStatus, StepError, StepSlots, StepStatus, WorkflowDocument } from './execution.types';
export interface ExecutionListItemView {
    id: string;
    workflowId: string;
    status: ExecutionStatus;
    mode: ExecutionMode;
    hostMode: string;
    createdAt: Date;
    updatedAt: Date;
    finishedAt: Date | null;
}
export interface ExecutionListQuery {
    workflowIds: readonly string[] | 'all';
    status?: ExecutionStatus[];
    hostMode?: string;
    createdAfter?: string;
    createdBefore?: string;
    before?: {
        createdAt: string;
        id: string;
    };
    limit: number;
    includeTotal?: boolean;
    order?: {
        top?: ExecutionStatus;
        startedAt?: 'DESC';
    };
}
export interface ExecutionView {
    id: string;
    workflowId: string;
    status: ExecutionStatus;
    mode: ExecutionMode;
    hostMode: string;
    graph: StoredWorkflowGraph;
    workflow: WorkflowDocument;
    createdAt: Date;
    updatedAt: Date;
    finishedAt: Date | null;
}
export interface StepView {
    id: string;
    nodeId: string;
    iteration: number;
    status: StepStatus;
    outputs: StepSlots | null;
    error: StepError | null;
    createdAt: string;
    updatedAt: string;
}
export interface ExecutionWithStepsView extends ExecutionView {
    steps: StepView[];
}
export interface ExecutionViewStore {
    listExecutionViews(query: ExecutionListQuery): Promise<ExecutionListItemView[]>;
    countExecutionViews(query: ExecutionListQuery): Promise<number>;
    loadExecutionView(id: string): Promise<ExecutionView>;
    loadExecutionWithStepsView(id: string): Promise<ExecutionWithStepsView>;
}
